using static NarrativeText;

public static class CorrespondenceText
{
    public static string Source(int voice)=>voice==0?"01":"02";
    public static string Status(MessageEnvelope item)=>NarrativeText.DispatchActive&&item.Assumed?L("铅笔排期 / 待核对","PENCILLED IN / UNCHECKED"):NarrativeText.DispatchActive&&item.PublicProgress!=0&&item.PublicProgress!=3?L("只带到了一项","ONE PIECE HEARD"):item.Status==MessageStatus.Delivered?L("已交付","DELIVERED"):item.Status==MessageStatus.Returned?L("承诺已退回","PROMISE RETURNED"):item.Status==MessageStatus.KeptPrivate?L("已经保密","KEPT PRIVATE"):item.Promised?L("答应转告","PROMISED TO PASS ON"):L("私下听见的需要","A PRIVATE NOTE");
    public static string Permission(MessageEnvelope item)=>item.Permission==MessagePermission.Granted?L("私下需要：已获转述许可","PRIVATE NEED: MAY BE SHARED"):item.Sharing==SharingPreference.OwnVoice&&item.HasNeed?L("私下需要：对方想亲口说。","PRIVATE NEED: THEY WANT TO SAY IT."):item.Permission==MessagePermission.Declined?L("私下需要：对方不愿公开","PRIVATE NEED: KEEP THIS PRIVATE"):L("私下需要：还没问过本人","PRIVATE NEED: ASK BEFORE SHARING");
    public static string Request(MessageEnvelope item)=>NarrativeText.DispatchActive?DispatchText.Fragment(CaseInfo.Active,item.Source,DispatchFragment.Fact)+"\n"+DispatchText.Fragment(CaseInfo.Active,item.Source,DispatchFragment.Request):CaseInfo.Active==CaseId.Office?(item.Source==0?L("“周五得拿到草稿，评审时间也请确认一下。”","I need the draft on Friday. Please confirm a time for the review."):L("“评审能改到白天吗？草稿我周五给。原因先不谈。”","Could we move the review to daytime? I'll have the draft on Friday. I'd rather not discuss why.")):LineAt(0,item.Source);
    public static string Need(MessageEnvelope item)=>!item.HasNeed?L("还没问清对方为什么提出这个请求。","You haven't heard why they're asking for this."):CaseInfo.Active==CaseId.Office?(item.Source==0?L("“我就怕东西交不出来，最后又落到我头上。”","I'm worried the work won't get done and I'll be left to deal with it."):L("“原因我现在不想谈。这句话，让我自己去说。”","I don't want to get into why. Let me say that myself.")):item.Source==0?L("“我就是想知道，他心里还有没有我。”","I just want to know I still have a place in his life."):L("“我想自己拿主意，也想和她好好来往。”","I want to make my own choices and still get along with her.");
    public static string Readiness(RelationshipRun run,MessageEnvelope item)=>run.DispatchRules?L("两段话可以分次说。先读对方的反应，再选顺序。","Words can be carried in stages. Read their reaction, then choose the order."):run.Trust(1-item.Source)>=2?L("收信人较信任你，能多听进一些。","The recipient trusts you enough to be more receptive."):L("收信人还在防备，原样转告责备会降低信任。","The recipient is guarded. Passing on blame will cost trust.");
    public static string Delta(CorrespondenceEvent result)=>NarrativeText.Delta(result.CapacityDelta,result.LoadDelta,result.BridgeDelta)+"\n"+Source(result.Source)+L(" 信任 "," TRUST ")+Signed(result.SourceTrustDelta)+"  /  "+Source(1-result.Source)+L(" 信任 "," TRUST ")+Signed(result.RecipientTrustDelta);
    public static string Outcome(CorrespondenceEvent result)
    {
        if(result.Packet)return DispatchText.Reaction(result);
        if(result.Action==MessageAction.Reconfirm)return L("“这次两项都对上了。我这部分可以。”","Both pieces match now. My part is fine.");
        if(result.Action==MessageAction.AskPermission&&result.PrefersOwnVoice)return L("“我愿意跟你说。这句话，我还是想自己讲。”\n对方没有同意让你转述。","I'm happy to tell you, but I'd like to say this myself.\nThey haven't given you permission to share it.");
        if(result.Action==MessageAction.AskPermission)return result.PermissionGranted?L("“这句可以转告。结果我可没法保证。”\n本人允许转述；要不要直接谈，还得另问。","You can tell them that. I can't promise how it'll go.\nYou have permission to share this. Agreeing to talk is a separate question."):L("“这句就先别告诉别人了。”\n对方不愿公开，这一轮不能再问。","Please keep that between us for now.\nThey don't want it shared. You can't ask again this round.");
        if(result.Action==MessageAction.Return)return result.WasPromise?L("你当面说明，没法继续替对方传这句话。\n对方有些失望，但知道了你的限度。","You tell the speaker you can't pass this on after all.\nThey're disappointed, but they know where you stand."):L("这句私下的话，你没有往外传。","You keep the private words between the two of you.");
        if(result.Action==MessageAction.Repair)return result.ConsentRenewed?L("你承认不该擅自转述，又问了一次。\n对方仍愿意直接谈；另一人的答复没有改变。","You acknowledge sharing without asking, then ask again.\nThey're still willing to talk. The other person's answer hasn't changed."):L("你承认了擅自转述，信任恢复了一点。\n对方有没有答应直接谈，仍按本人原先的答复。","You acknowledge sharing without asking. Some trust returns.\nTheir earlier answer about talking still stands.");
        if(result.Breach)return L("收信人听进去了，说这句话的人却没有同意让你转告。\n本人对你的信任下降；先前若答应过直接谈，这份同意也会撤回。","The recipient takes it in, but the speaker never agreed to have it shared.\nThey trust you less and withdraw any earlier agreement to talk.");
        if(result.Payload==MessagePayload.Need)return L("“这样说，我就明白了。”\n你把获准转述的那句话送到了。","That makes more sense to me.\nYou've passed on the words the speaker agreed to share.");
        if(CaseInfo.Active==CaseId.Office)return result.Source==1
            ?(result.RecipientReady?L("“周五草稿，白天评审。我听到了。\n下一步，让本人来确认这份安排。”\n公开请求已送到；是否愿意直接谈，仍须另外询问。","A Friday draft and a daytime review. I've heard the request.\nNow I need them to confirm the plan.\nThe public request has arrived. Agreement to talk still needs to be asked for."):L("“清单我收到了，但我还不能答应。”\n请求已经送到，对方仍有防备。","I have the request. I can't agree to it yet.\nThe request has arrived, but the manager is still guarded."))
            :L("“期限我听见了。能不能把工作安排单独说清楚？”\n公开请求已送到，私下的话没有一并带出。","I've heard the deadline. Can we make the work plan clear?\nThe public request has arrived. The private part stays out.");
        return result.RecipientReady?L("对方听你把原话说完了。\n接下来怎么答，还得由本人决定。","They hear the message out.\nHow they answer is up to them."):L("“所以，又是让我照着办？”\n话是原话，对方听着仍像责备。","So I'm being told what to do again?\nThe wording is accurate. To the listener, it still sounds like blame.");
    }
    public static string ActionName(MessageAction action)=>action==MessageAction.Deliver?L("交付","DELIVERY"):action==MessageAction.AskPermission?L("询问转述许可","ASK PERMISSION"):action==MessageAction.Repair?L("承认擅自转述","ACKNOWLEDGE BREACH"):action==MessageAction.Reconfirm?L("再问一次安排","CONFIRM THE PLAN AGAIN"):L("退回或保密","RETURN / KEEP PRIVATE");
}
